"use client";

/**
 * Tuner. A number picked the way a radio is tuned: a long scale printed on
 * the screen slides under a fixed, lit needle, and the reading above it
 * follows. Drag it and it moves with your hand; flick it and it coasts, then
 * settles onto a step; every tick that passes the needle clicks. Past either
 * end it gives a little and springs back. The scale's numbers dim toward both
 * edges, so the strip reads as a drum turning away from you.
 *
 * It fits a big range into a small width: the range scrolls instead of being
 * squeezed, so every step stays a finger's width apart (weight, height, a tip,
 * a zoom level, a frequency).
 *
 * For assistive technology it is a slider: `role="slider"` named by `label`,
 * with the reading and its unit as `aria-valuetext`, and every slider key:
 * arrows step, Page Up/Down move a numbered tick, Home and End go to the ends.
 */
import {
  forwardRef,
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type MutableRefObject,
  type PointerEvent,
} from "react";
import type { EchoInterop } from "echo-ui-core/types";
import { createSpring, rubberband, useReducedMotionRef, type Spring } from "echo-ui-core/tactile";
import { useSoundOptional, type SoundRecipe } from "echo-ui-core/sound";
import { SegmentDisplay } from "../segment-display";
import { decimalsFor, digitsFor, indexOf, lastIndex, niceLabelEvery, projectFlick, tickKind, valueAt } from "./scale";
import "../scope/scope.css";
import "./tuner.css";

export interface TunerProps extends EchoInterop {
  /** What it sets: the machine label over the reading, and the accessible name. */
  label: string;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Engraved after the reading, and said with it: "kg", "MHz". */
  unit?: string;
  /** The numbered ticks, in value units. Default: the nicest number that's at least eight steps. */
  labelEvery?: number;
  /** How the value is said to assistive technology. Default: the reading and its unit ("72.5 kg"). */
  formatValue?: (value: number) => string;
  /** `emissive` (default): a dark screen that glows. `reflective`: the paper-coloured glass of a pocket calculator, printed in ink. */
  screen?: "emissive" | "reflective";
}

/** Pixels between two steps on the scale. */
const SPACING = 10;
/** Ticks drawn each side of the needle: wider than any scale is shown. */
const REACH = 72;
const DETENT: SoundRecipe = { wave: "square", freq: 2200, decay: 0.012, gain: 0.045 };
const FOLLOW = { duration: 0.28, bounce: 0 };
const GLIDE = { duration: 0.7, bounce: 0 };

/**
 * `forwardRef`, not a `ref` prop — see the note on `Field`. The ref lands on
 * the slider element, which is what a form library focuses.
 */
export const Tuner = forwardRef<HTMLDivElement, TunerProps>(function Tuner(
  {
    label,
    value,
    defaultValue,
    onValueChange,
    min = 0,
    max = 100,
    step = 1,
    unit,
    labelEvery,
    formatValue,
    screen = "emissive",
    disabled = false,
    name,
    onKeyDown: onKeyDownProp,
    ...interop
  },
  ref,
) {
  const last = lastIndex(min, max, step);
  const every = labelEvery ?? niceLabelEvery(step);
  const [inner, setInner] = useState(() => indexOf(defaultValue ?? min, min, max, step));
  const index = value === undefined ? inner : indexOf(value, min, max, step);
  const current = valueAt(index, min, step);

  const sound = useSoundOptional();
  const reduced = useReducedMotionRef();
  const scale = useRef<HTMLDivElement | null>(null);
  const strip = useRef<SVGGElement>(null);
  const spring = useRef<Spring | null>(null);
  const committed = useRef(index);
  committed.current = index;
  /** The index the ticks were drawn around, so a frame between renders lines up with what's drawn. */
  const drawnAround = useRef(index);
  drawnAround.current = index;
  /**
   * Who is moving the scale. Under the hand (a drag or a flick) the reading
   * follows the scale step by step, each one clicking; sent by a key or from
   * outside, the reading is already decided and the scale just travels there.
   */
  const mover = useRef<"hand" | "set">("set");
  /** The index the scale itself last reported, so its own report isn't mistaken for a change from outside. */
  const reported = useRef(index);
  const drag = useRef<{ x: number; from: number; samples: { x: number; t: number }[] } | null>(null);

  const place = useCallback((position: number) => {
    const g = strip.current;
    if (g) g.setAttribute("transform", `translate(${(drawnAround.current * SPACING - position).toFixed(2)} 0)`);
  }, []);

  const commit = useCallback(
    (next: number) => {
      const i = Math.min(last, Math.max(0, next));
      reported.current = i;
      if (i === committed.current) return;
      committed.current = i;
      if (value === undefined) setInner(i);
      sound?.play(DETENT);
      onValueChange?.(valueAt(i, min, step));
    },
    [last, value, sound, onValueChange, min, step],
  );
  const commitRef = useRef(commit);
  commitRef.current = commit;

  // One spring for the scale's whole life: it follows a drag, carries a
  // flick, and settles on each step.
  useEffect(() => {
    spring.current = createSpring(committed.current * SPACING, FOLLOW, (position) => {
      place(position);
      if (mover.current === "hand") commitRef.current(Math.round(position / SPACING));
    });
    return () => spring.current?.stop();
  }, [place]);

  // A reading set from outside travels there.
  useEffect(() => {
    const s = spring.current;
    if (!s || drag.current || index === reported.current) return;
    reported.current = index;
    mover.current = "set";
    if (reduced.current) s.set(index * SPACING);
    else s.to(index * SPACING, { config: FOLLOW });
  }, [index, reduced]);

  // After a render the ticks are drawn around the new index: line them up.
  useLayoutEffect(() => {
    place(spring.current?.value ?? index * SPACING);
  });

  /* Dragging: the scale moves 1:1 with the hand, and gives past the ends. */
  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (disabled || e.button !== 0) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    e.currentTarget.focus();
    mover.current = "hand";
    const from = spring.current?.value ?? index * SPACING;
    spring.current?.set(from);
    drag.current = { x: e.clientX, from, samples: [{ x: e.clientX, t: e.timeStamp }] };
  };
  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d) return;
    const raw = d.from - (e.clientX - d.x);
    const end = last * SPACING;
    const past = raw < 0 ? raw : raw > end ? raw - end : 0;
    const at = past ? (raw < 0 ? 0 : end) + rubberband(past, 120) : raw;
    d.samples.push({ x: e.clientX, t: e.timeStamp });
    if (d.samples.length > 6) d.samples.shift();
    spring.current?.set(at);
  };
  const onPointerUp = (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    drag.current = null;
    const s = spring.current;
    if (!d || !s) return;
    const first = d.samples[0]!;
    const final = d.samples[d.samples.length - 1]!;
    const span = (final.t - first.t) / 1000;
    // Pointer velocity, in scale units per second (the scale runs against the hand).
    const velocity = span > 0 && e.timeStamp - final.t < 90 ? -(final.x - first.x) / span : 0;
    if (reduced.current) {
      s.set(Math.min(last, Math.max(0, Math.round(s.value / SPACING))) * SPACING);
      return;
    }
    s.to(projectFlick(s.value, velocity, SPACING, last), { config: velocity ? GLIDE : FOLLOW, velocity });
  };

  /** Go to a step decided up front (a key, the wheel): the reading changes once, the scale travels. */
  const goTo = useCallback(
    (next: number) => {
      const to = Math.min(last, Math.max(0, next));
      mover.current = "set";
      commitRef.current(to);
      const s = spring.current;
      if (!s) return;
      if (reduced.current) s.set(to * SPACING);
      else s.to(to * SPACING, { config: FOLLOW });
    },
    [last, reduced],
  );

  // A sideways wheel or trackpad swipe turns it; an up/down wheel only once
  // it has focus, so scrolling a page never catches on it. Native listener:
  // React's are passive and couldn't keep the page still.
  useEffect(() => {
    const el = scale.current;
    if (!el) return;
    const wheel = (e: WheelEvent) => {
      if (disabled) return;
      const sideways = Math.abs(e.deltaX) > Math.abs(e.deltaY);
      if (!sideways && document.activeElement !== el) return;
      e.preventDefault();
      const by = sideways ? e.deltaX : -e.deltaY;
      if (Math.abs(by) < 1) return;
      goTo(committed.current + Math.sign(by) * Math.max(1, Math.round(Math.abs(by) / SPACING)));
    };
    el.addEventListener("wheel", wheel, { passive: false });
    return () => el.removeEventListener("wheel", wheel);
  }, [disabled, goTo]);

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    // The caller's handler runs first and may take the key for itself.
    onKeyDownProp?.(e);
    if (e.defaultPrevented || disabled) return;
    const big = Math.max(1, Math.round(every / step));
    const at = committed.current;
    const next =
      e.key === "ArrowRight" || e.key === "ArrowUp"
        ? at + 1
        : e.key === "ArrowLeft" || e.key === "ArrowDown"
          ? at - 1
          : e.key === "PageUp"
            ? at + big
            : e.key === "PageDown"
              ? at - big
              : e.key === "Home"
                ? 0
                : e.key === "End"
                  ? last
                  : null;
    if (next === null) return;
    e.preventDefault();
    goTo(next);
  };

  const reading = current.toFixed(decimalsFor(min, step));
  const said = formatValue ? formatValue(current) : unit ? `${reading} ${unit}` : reading;

  // The ticks round the needle, drawn about the current index.
  const ticks: { x: number; kind: ReturnType<typeof tickKind>; label?: string }[] = [];
  for (let i = Math.max(0, index - REACH); i <= Math.min(last, index + REACH); i++) {
    const kind = tickKind(i, min, step, every);
    ticks.push({ x: (i - index) * SPACING, kind, label: kind === "major" ? String(valueAt(i, min, step)) : undefined });
  }
  const span = REACH * SPACING;

  return (
    <div className="echo-tuner" data-disabled={disabled || undefined}>
      <div className="echo-tuner__screen" data-echo-screen={screen === "reflective" ? "reflective" : undefined}>
        <span className="echo-tuner__label" aria-hidden="true">
          {label}
        </span>
        <div className="echo-tuner__reading" aria-hidden="true">
          <SegmentDisplay
            variant="flush"
            label={label}
            value={reading}
            digits={digitsFor(min, max, step)}
            unit={unit}
          />
        </div>
        <div
          ref={(node) => {
            scale.current = node;
            if (typeof ref === "function") ref(node);
            else if (ref) (ref as MutableRefObject<HTMLDivElement | null>).current = node;
          }}
          className="echo-tuner__scale"
          role="slider"
          tabIndex={disabled ? -1 : 0}
          aria-label={label}
          aria-valuemin={min}
          aria-valuemax={valueAt(last, min, step)}
          aria-valuenow={current}
          aria-valuetext={said}
          aria-orientation="horizontal"
          aria-disabled={disabled || undefined}
          {...interop}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={onPointerUp}
          onPointerCancel={onPointerUp}
          onKeyDown={onKeyDown}
        >
          <div className="echo-tuner__drum" aria-hidden="true">
            <svg className="echo-tuner__ticks" viewBox={`${-span} 0 ${2 * span} 64`} width={2 * span} height={64}>
              <g ref={strip}>
                {ticks.map((t) => (
                  <g key={t.x}>
                    <line x1={t.x} x2={t.x} y1={6} y2={t.kind === "major" ? 30 : t.kind === "mid" ? 21 : 14} data-kind={t.kind} />
                    {t.label !== undefined ? (
                      <text x={t.x} y={50}>
                        {t.label}
                      </text>
                    ) : null}
                  </g>
                ))}
              </g>
            </svg>
          </div>
          <span className="echo-tuner__needle" aria-hidden="true" />
        </div>
      </div>
      {name ? <input type="hidden" name={name} value={current} /> : null}
    </div>
  );
});

/**
 * Tuner. A dark screen well holding the reading and a scale printed on the
 * glass, with a lit needle fixed over it. The needle is the accent because it
 * emits; the scale is cream print. Composes var(--echo-*) — no hex literals;
 * the only fixed values are the single-key-light occlusion model.
 */
.echo-tuner {
  display: block;
  inline-size: 100%;
  max-inline-size: 100%;
  min-inline-size: 0;
}

.echo-tuner__screen {
  display: grid;
  gap: var(--echo-space-3);
  padding-block-start: var(--echo-space-6);
  border-radius: var(--echo-radius-xl);
  background: var(--echo-drawn-glass, linear-gradient(160deg, var(--echo-well) 0%, var(--echo-lcd) 100%));
  box-shadow: var(
    --echo-shadow-well-deep,
    inset 0 3px 7px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.9 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent)
  );
  overflow: hidden;
}

.echo-tuner__label {
  padding-inline: var(--echo-space-8);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-widest, 0.25em);
  text-transform: uppercase;
  color: var(--echo-text-dim);
}

.echo-tuner__reading {
  display: flex;
  justify-content: center;
  padding-inline: var(--echo-space-8);
}

/* The scale: numbers read left to right in every language. */
.echo-tuner__scale {
  position: relative;
  block-size: 64px;
  direction: ltr;
  cursor: grab;
  touch-action: pan-y;
  user-select: none;
  outline: none;
  border-radius: 0 0 var(--echo-radius-xl) var(--echo-radius-xl);
}
.echo-tuner__scale:active {
  cursor: grabbing;
}
.echo-tuner__scale:focus-visible {
  box-shadow: var(--echo-shadow-ring-inset, inset 0 0 0 2px var(--echo-accent-ink, var(--echo-accent-glow)));
}

/* The drum: the print fades toward both edges, as a scale turning away does. */
.echo-tuner__drum {
  position: absolute;
  inset: 0;
  overflow: hidden;
  /* The print runs on past the window on purpose: it's a strip, clipped. */
  --echo-clip: decorative;
  -webkit-mask-image: linear-gradient(90deg, transparent 0, var(--echo-seam) 30%, var(--echo-seam) 70%, transparent 100%);
  mask-image: linear-gradient(90deg, transparent 0, var(--echo-seam) 30%, var(--echo-seam) 70%, transparent 100%);
}
.echo-tuner__ticks {
  position: absolute;
  inset-block-start: 0;
  inset-inline-start: 50%;
  translate: -50% 0;
  overflow: visible;
}
.echo-tuner__ticks line {
  stroke: color-mix(in oklab, var(--echo-text) 32%, transparent);
  stroke-width: 2;
  stroke-linecap: round;
}
.echo-tuner__ticks line[data-kind="mid"] {
  stroke: color-mix(in oklab, var(--echo-text) 55%, transparent);
}
.echo-tuner__ticks line[data-kind="major"] {
  stroke: color-mix(in oklab, var(--echo-text) 85%, transparent);
}
.echo-tuner__ticks text {
  fill: var(--echo-text-dim);
  font-family: var(--echo-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--echo-text-xs);
  font-variant-numeric: tabular-nums;
  text-anchor: middle;
}

/* The needle: the one lit thing on the scale. A stem with a round head. */
.echo-tuner__needle {
  position: absolute;
  inset-block-start: 1px;
  inset-inline-start: 50%;
  inline-size: 8px;
  block-size: 34px;
  margin-inline-start: -4px;
  pointer-events: none;
}
.echo-tuner__needle::before,
.echo-tuner__needle::after {
  content: "";
  position: absolute;
  inset-inline-start: 50%;
  translate: -50% 0;
  background: var(--echo-accent-glow);
  box-shadow: 0 0 8px color-mix(in oklab, var(--echo-lcd-glow) 70%, transparent);
}
.echo-tuner__needle::before {
  inset-block: 3px 0;
  inline-size: 2px;
  border-radius: var(--echo-radius-full);
}
.echo-tuner__needle::after {
  inset-block-start: 0;
  inline-size: 8px;
  block-size: 8px;
  border-radius: 50%;
}

.echo-tuner[data-disabled] {
  opacity: 0.45;
}
.echo-tuner[data-disabled] .echo-tuner__scale {
  cursor: default;
}

@media (forced-colors: active) {
  .echo-tuner__screen {
    border: var(--echo-border-hairline, 1px) solid CanvasText;
  }
  .echo-tuner__ticks line,
  .echo-tuner__ticks line[data-kind] {
    stroke: CanvasText;
  }
  .echo-tuner__ticks text {
    fill: CanvasText;
  }
  .echo-tuner__needle::before,
  .echo-tuner__needle::after {
    background: Highlight;
    box-shadow: none;
  }
  .echo-tuner__scale:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}

/**
 * The tuner's scale, as numbers. Pure: no React, no DOM, so the tick rules
 * and the value arithmetic can be tested on their own.
 *
 * A value lives on the scale as a step index (0 at `min`); positions are
 * index × the spacing between ticks. Working in whole steps is what keeps
 * 0.1 + 0.2 from turning up as 0.30000000000000004 on a readout.
 */

/** How many decimals a step needs: 0.5 → 1, 0.25 → 2, 5 → 0. */
export function decimalsOf(step: number): number {
  const text = String(step);
  if (text.includes("e-")) return Number(text.split("e-")[1]);
  return text.includes(".") ? text.split(".")[1]!.length : 0;
}

/**
 * How many decimals the scale's values need: the step's or `min`'s, whichever
 * has more. 87.5 by 1 reads 87.5, 88.5, 89.5, never 88, 89, 90.
 */
export function decimalsFor(min: number, step: number): number {
  return Math.max(decimalsOf(step), decimalsOf(min));
}

/** The value at a step index, rounded to the scale's decimals. */
export function valueAt(index: number, min: number, step: number): number {
  return Number((min + index * step).toFixed(decimalsFor(min, step)));
}

/**
 * The index of the last step inside the range. A range that isn't a whole
 * number of steps stops short of `max` (0 to 10 by 4 ends on 8), never past
 * it. The tolerance keeps a float quotient like 204.99999999999997 whole.
 */
export function lastIndex(min: number, max: number, step: number): number {
  return Math.max(0, Math.floor((max - min) / step + 1e-9));
}

/** The nearest step index to a value, inside the scale. */
export function indexOf(value: number, min: number, max: number, step: number): number {
  return Math.min(lastIndex(min, max, step), Math.max(0, Math.round((value - min) / step)));
}

/**
 * How far apart the numbered ticks are, in value units: the smallest "nice"
 * number (1, 2, 2.5 or 5 × a power of ten) that is at least eight steps, so
 * a label lands every eight to twenty ticks whatever the step.
 */
export function niceLabelEvery(step: number): number {
  const want = step * 8;
  const power = 10 ** Math.floor(Math.log10(want));
  for (const m of [1, 2, 2.5, 5, 10]) {
    const candidate = m * power;
    if (candidate >= want - 1e-9 && isWhole(candidate / step)) return Number(candidate.toPrecision(12));
  }
  return step * 10;
}

const isWhole = (n: number) => Math.abs(n - Math.round(n)) < 1e-9;

export type TickKind = "minor" | "mid" | "major";

/**
 * What a tick is: `major` where a label goes, `mid` halfway between labels
 * (when that falls on a step), `minor` everywhere else.
 *
 * Labels sit on round values (88, 89, 90 on a radio that starts at 87.5 by
 * 0.1). When no step ever lands on a round value (87.5 by 1), they're counted
 * from `min` instead, so the scale still has numbers.
 */
export function tickKind(index: number, min: number, step: number, labelEvery: number): TickKind {
  const anchor = isWhole(min / step) ? 0 : min;
  const value = min + index * step - anchor;
  if (isWhole(value / labelEvery)) return "major";
  const half = labelEvery / 2;
  if (isWhole(half / step) && isWhole(value / half)) return "mid";
  return "minor";
}

/**
 * Where a flick lands: the release velocity carried on for a moment, the way
 * a thrown dial coasts, then onto the nearest step and inside the scale.
 */
export function projectFlick(position: number, velocity: number, spacing: number, last: number): number {
  const COAST = 0.32;
  const landing = Math.round((position + velocity * COAST) / spacing);
  return Math.min(last, Math.max(0, landing)) * spacing;
}

/**
 * How many cells the readout needs to fit every value on the scale, so its
 * width never changes as the value does. A scale that goes below zero keeps a
 * cell for the minus.
 */
export function digitsFor(min: number, max: number, step: number): number {
  const d = decimalsFor(min, step);
  const widest = Math.max(Math.abs(min), Math.abs(max)).toFixed(d);
  return widest.replace(/[^0-9]/g, "").length + (min < 0 ? 1 : 0);
}
